"use client";import {useEffect,useMemo,useState} from "react";import {Activity,ArrowRight,CheckCircle2,Clock3,GitBranch,LayoutDashboard,Loader2,Plus,ShieldCheck,Timer,Workflow as WorkflowIcon,XCircle,ChevronRight} from "lucide-react";import type {Workflow} from "@/lib/types";
const nav=[['Overview',LayoutDashboard],['Create Workflow',Plus],['Active Workflows',Activity],['Pending Approvals',ShieldCheck],['Workflow History',Clock3]] as const;
const colors:Record<string,string>={sleeping:'text-blue-700 bg-blue-50',waiting:'text-amber-700 bg-amber-50',running:'text-violet-700 bg-violet-50',completed:'text-emerald-700 bg-emerald-50',approved:'text-emerald-700 bg-emerald-50',rejected:'text-red-700 bg-red-50',failed:'text-red-700 bg-red-50',pending:'text-slate-700 bg-slate-100'};
function Badge({status}:{status:string}){return <span className={'status '+(colors[status]||colors.pending)}><i className="dot"/>{status.replace('waiting','Waiting for approval')}</span>}
export default function Dashboard(){const [items,setItems]=useState<Workflow[]>([]);const [tab,setTab]=useState('Overview');const [kind,setKind]=useState('sleep');const [loading,setLoading]=useState(false);const [form,setForm]=useState<Record<string,string>>({name:'',message:'',delay:'3',unit:'minutes',title:'',description:'',requester:'',deadline:'24',service:'',version:'',});const load=()=>fetch('/api/workflows').then(r=>r.json()).then(setItems);useEffect(()=>{load()},[]);const stats=useMemo(()=>({total:items.length,running:items.filter(x=>['running','sleeping'].includes(x.status)).length,waiting:items.filter(x=>x.status==='waiting').length,approved:items.filter(x=>x.status==='approved').length,rejected:items.filter(x=>x.status==='rejected').length,failed:items.filter(x=>x.status==='failed').length}),[items]);const set=(k:string,v:string)=>setForm(x=>({...x,[k]:v}));async function submit(e:React.FormEvent){e.preventDefault();setLoading(true);const body=kind==='sleep'?{kind,...form}:kind==='approval'?{kind,...form}:{kind,...form};await fetch('/api/workflows',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});setLoading(false);setTab('Active Workflows');load()}async function decision(id:string,decision:string){await fetch('/api/approvals',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,decision})});load()}
return <div className="min-h-screen flex"><aside className="w-64 shrink-0 bg-[#1d2638] text-white p-5 hidden md:block"><div className="flex items-center gap-3 px-2 mb-10"><div className="h-8 w-8 rounded-lg bg-[#635bff] grid place-items-center"><GitBranch size={18}/></div><span className="font-bold tracking-tight">flowdesk</span></div><div className="text-[10px] uppercase tracking-widest text-slate-500 px-3 mb-3">Workspace</div><nav className="space-y-1">{nav.map(([n,I])=><button key={n} onClick={()=>setTab(n)} className={'nav-link w-full '+(tab===n?'active':'')}><I size={17}/>{n}</button>)}</nav><div className="absolute bottom-7 text-xs text-slate-500 px-3">Inngest demo · Local mode</div></aside><main className="flex-1 min-w-0"><header className="h-16 bg-white border-b border-line flex items-center justify-between px-6 lg:px-10"><div className="flex items-center gap-2 text-sm text-muted"><span>Workspace</span><ChevronRight size={15}/><span className="text-ink font-medium">{tab}</span></div><div className="flex items-center gap-3"><span className="hidden sm:inline text-xs text-slate-500">Local development</span><div className="h-8 w-8 rounded-full bg-indigo-100 text-indigo-700 grid place-items-center text-xs font-bold">AD</div></div></header><div className="p-6 lg:p-10 max-w-[1400px] mx-auto"><div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 mb-8"><div><p className="text-sm text-muted mb-2">Sunday, November 1, 2026</p><h1 className="text-3xl font-bold tracking-tight">{tab==='Create Workflow'?'Create a workflow':tab}</h1><p className="text-muted mt-2">Build reliable background work with durable execution.</p></div>{tab!=='Create Workflow'&&<button className="btn btn-primary flex items-center gap-2 w-fit" onClick={()=>setTab('Create Workflow')}><Plus size={17}/> New workflow</button>}</div>{tab==='Create Workflow'?<form onSubmit={submit} className="card p-6 max-w-3xl"><div className="flex gap-2 border-b border-line pb-4 mb-6">{[['sleep','Sleep & delay'],['approval','Human approval'],['deployment','Deployment']].map(([v,l])=><button type="button" key={v} onClick={()=>setKind(v)} className={'px-3 py-2 text-sm rounded-lg '+(kind===v?'bg-indigo-50 text-brand font-semibold':'text-muted')}>{l}</button>)}</div>{kind==='sleep'?<><Field label="Workflow name" value={form.name} onChange={v=>set('name',v)} placeholder="Take a Break"/><Field label="Message" value={form.message} onChange={v=>set('message',v)} placeholder="Time to sleep!"/><div className="grid grid-cols-2 gap-4"><Field label="Delay duration" value={form.delay} onChange={v=>set('delay',v)} type="number"/><div><label className="label">Delay unit</label><select className="field" value={form.unit} onChange={e=>set('unit',e.target.value)}><option>seconds</option><option>minutes</option></select></div></div></>:kind==='approval'?<><Field label="Request title" value={form.title} onChange={v=>set('title',v)} placeholder="Publish New Article"/><Field label="Description" value={form.description} onChange={v=>set('description',v)} placeholder="I want permission to publish an article."/><div className="grid grid-cols-2 gap-4"><Field label="Requester name" value={form.requester} onChange={v=>set('requester',v)} placeholder="Abdullahi"/><Field label="Approval deadline (hours)" value={form.deadline} onChange={v=>set('deadline',v)} type="number"/></div></>:<><Field label="Service name" value={form.service} onChange={v=>set('service',v)} placeholder="payments-api"/><div className="grid grid-cols-2 gap-4"><Field label="Version" value={form.version} onChange={v=>set('version',v)} placeholder="v2.4.0"/><Field label="Requester name" value={form.requester} onChange={v=>set('requester',v)} placeholder="Abdullahi"/></div></>}<button disabled={loading} className="btn btn-primary mt-3 flex items-center gap-2">{loading?<Loader2 className="animate-spin" size={16}/>:<ArrowRight size={16}/>} Start workflow</button></form>:<><div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-4 mb-8">{[['Total workflows',stats.total,WorkflowIcon],['Running',stats.running,Activity],['Waiting',stats.waiting,Timer],['Approved',stats.approved,CheckCircle2],['Rejected',stats.rejected,XCircle],['Failed',stats.failed,ShieldCheck]].map(([l,v,I])=><div className="card p-4" key={l as string}><div className="flex justify-between text-muted text-xs mb-4"><span>{l as string}</span><I size={16}/></div><div className="text-2xl font-bold">{v as number}</div></div>)}</div><section className="card overflow-hidden"><div className="p-5 border-b border-line flex items-center justify-between"><div><h2 className="font-semibold">{tab==='Pending Approvals'?'Pending approvals':'Recent workflows'}</h2><p className="text-sm text-muted mt-1">Your workflow activity at a glance</p></div><button onClick={load} className="text-sm text-brand font-semibold">Refresh</button></div>{items.length===0?<div className="py-20 text-center"><WorkflowIcon className="mx-auto text-slate-300 mb-3" size={38}/><p className="font-medium">No workflows yet</p><p className="text-sm text-muted mt-1">Start your first workflow to see it here.</p></div>:<div className="divide-y divide-line">{items.filter(x=>tab!=='Pending Approvals'||x.status==='waiting').map(x=><div key={x.id} className="p-5 flex flex-col md:flex-row md:items-center gap-4 justify-between"><div className="flex items-start gap-4"><div className="h-10 w-10 rounded-lg bg-slate-100 grid place-items-center text-muted"><WorkflowIcon size={18}/></div><div><div className="font-semibold">{x.name}</div><div className="text-xs text-muted mt-1">{x.kind} · {new Date(x.createdAt).toLocaleString()}</div></div></div><div className="flex items-center gap-4"><Badge status={x.status}/>{x.status==='waiting'&&<><button onClick={()=>decision(x.id,'approved')} className="btn btn-primary py-2">Approve</button><button onClick={()=>decision(x.id,'rejected')} className="btn btn-danger py-2">Reject</button></>}</div></div>)}</div>}</section></>}</div></main></div>}
function Field({label,value,onChange,placeholder,type='text'}:{label:string;value:string;onChange:(v:string)=>void;placeholder?:string;type?:string}){return <div className="mb-4"><label className="label">{label}</label><input required type={type} className="field" value={value} placeholder={placeholder} onChange={e=>onChange(e.target.value)}/></div>}
